SELECT COUNT(*) FROM BSYCADF CADF
 WHERE CADF.CODE_GROUP_ID = #{CODE_GROUP_ID}
   AND CADF.ATTRIBUTE_CODE = #{ATTRIBUTE_CODE}
   AND CADF.DEL_YN = 'N'

   AND CADF.ATTRIBUTE_DEF_ID != #{EXCLUDE_ATTRIBUTE_DEF_ID}

mapper.update:
UPDATE BSYCAVL SET ATTRIBUTE_VALUE = #{ATTRIBUTE_VALUE}, DEL_YN = 'N',
       MOD_DT = CURRENT_TIMESTAMP, MOD_BY = #{ACTOR}
 WHERE CODE_ID = #{CODE_ID} AND ATTRIBUTE_DEF_ID = #{ATTRIBUTE_DEF_ID}
